import{_ as o,C as t,o as a,c as l,a4 as n,E as r}from"./chunks/framework.BNWYI55R.js";const m=JSON.parse('{"title":"关于本站：aijichang.blog 的使命、定位与独立宣言","description":"关于 aijichang.blog。面向 AI 生产力与全球流媒体中文用户，提供真实套餐、具体任务与可追溯记录的独立评测指南。","frontmatter":{"title":"关于本站：aijichang.blog 的使命、定位与独立宣言","description":"关于 aijichang.blog。面向 AI 生产力与全球流媒体中文用户，提供真实套餐、具体任务与可追溯记录的独立评测指南。","h1":"关于本站：aijichang.blog 的使命、定位与独立宣言","pageType":"article","canonicalPath":"/about/","primaryIntent":"关于我们：了解本站的创立背景、独立价值观与技术路线","verifiedAt":"2026-10-21T00:00:00.000Z","modifiedAt":"2026-10-21T00:00:00.000Z"},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md","lastUpdated":1792563027000}'),s={name:"about/index.md"};function c(d,i,g,h,u,p){const e=t("RelatedLinks");return a(),l("div",null,[i[0]||(i[0]=n('<h1 id="关于本站-aijichang-blog-的使命、定位与独立宣言" tabindex="-1">关于本站：aijichang.blog 的使命、定位与独立宣言 <a class="header-anchor" href="#关于本站-aijichang-blog-的使命、定位与独立宣言" aria-label="Permalink to &quot;关于本站：aijichang.blog 的使命、定位与独立宣言&quot;">​</a></h1><p>欢迎来到 <strong>aijichang.blog（AI机场）</strong>。</p><p>在中文互联网的跨境网络选购领域，长期存在着两个极端的困境：</p><ul><li>一边是充斥着机器批量采集、虚高原价与诱导冲动消费的推广导航站。它们只看哪家佣金高就无脑吹捧哪家，把“全网最稳、全平台全绿”当成不要钱的口头禅，对用户的晚高峰断流与封号风险只字不提；</li><li>另一边是晦涩难懂的极客论坛。技术讨论充斥着大量缩写（BGP/IEPL/FUP/SNI/L3），普通用户只是想顺畅写一段代码或看一部美剧，却不得不被迫先花几天时间学习复杂的网络协议。</li></ul><p><strong>aijichang.blog 创立的初衷，正是为了打破这种信息不对称。</strong></p><hr><h2 id="我们的核心定位" tabindex="-1">我们的核心定位 <a class="header-anchor" href="#我们的核心定位" aria-label="Permalink to &quot;我们的核心定位&quot;">​</a></h2><p><strong>面向使用 ChatGPT、Claude、Gemini 以及 Netflix、Disney+、YouTube、TikTok 的中文用户，依据真实套餐、具体任务和可追溯记录选择机场。</strong></p><p>我们不是泛 AI 工具导航站，不售卖账号，不提供 API 中转，也不盲目罗列没有实测依据的技术指令。我们的所有内容与技术工具，纯粹服务于一个明确目标：<strong>帮你用最合理的预算，找到最能稳定跑通你具体生产力与娱乐任务的网络方案</strong>。</p><hr><h2 id="我们的四大独立原则" tabindex="-1">我们的四大独立原则 <a class="header-anchor" href="#我们的四大独立原则" aria-label="Permalink to &quot;我们的四大独立原则&quot;">​</a></h2><ol><li><strong>真实可追溯（Evidence-Based）</strong>： <ul><li>拒绝毫无意义的“全绿九宫格”假图；</li><li>每一条测试结论必须明确标注测试时间戳、运营商基线网络、具体执行任务与失败重试样本；</li><li>未经验证的项目严格标注为 <code>null</code> 或 <code>待测试</code>，绝不脑补；</li></ul></li><li><strong>算清真实全周期账本（True Cost Accounting）</strong>： <ul><li>坚决将“一次性预付实付款（Actual Payment）”与“折算月均价（Effective Monthly Cost）”分立展示；</li><li>严厉揭露首年打折次年天价、高倍率计费刺客、单设备限速等霸王条款；</li></ul></li><li><strong>技术栈极简与纯静态（Clean &amp; Static）</strong>： <ul><li>整站采用 VitePress + Vue 3 + TypeScript 构建，搭配 Pagefind 纯静态检索，部署于高性能 Apache 环境；</li><li>坚持纯白、克制、无干扰的视觉风格，移动端优先，零第三方冗余追踪脚本；</li></ul></li><li><strong>商业利益透明披露（Transparent Commercialization）</strong>： <ul><li>本站客观呈现部分合规推广链接以维持服务器开销，所有推广链接在底层均明确标记 <code>rel=&quot;nofollow sponsored noopener&quot;</code>；</li><li>商业合作绝不左右评测事实。对断流严重或存在跑路风险的品牌，无论佣金多高一律如实曝光并亮红灯警示。读者的长期信任是本站最宝贵的核心资产。</li></ul></li></ol><hr><h2 id="站点技术参数" tabindex="-1">站点技术参数 <a class="header-anchor" href="#站点技术参数" aria-label="Permalink to &quot;站点技术参数&quot;">​</a></h2><ul><li><strong>生产域名</strong>：<code>https://aijichang.blog</code></li><li><strong>技术框架</strong>：VitePress 1.6.4 (Vue 3.5.13 + Vite 6.0.11)</li><li><strong>搜索方案</strong>：Pagefind 1.5.2 纯静态索引（浏览器端 WASM 极速检索）</li><li><strong>服务器架构</strong>：Apache 纯静态托管，配置标准 <code>.htaccess</code> 安全与缓存策略</li></ul>',15)),r(e,{links:[{title:"四层评测方法论 (/methodology/)",desc:"深入了解资格、网络、任务与体验四层测评模型",url:"/methodology/"},{title:"商业披露与赞助政策 (/disclosure/)",desc:"查阅本站的推广佣金分成白皮书与中立底线",url:"/disclosure/"},{title:"勘误与更正归档 (/corrections/)",desc:"查阅历史测试数据修正记录，提交你的实测反馈",url:"/corrections/"}]})])}const _=o(s,[["render",c]]);export{m as __pageData,_ as default};
